package com.lqq.supportflow.ticket.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.lqq.supportflow.ticket.domain.*; import java.time.Instant; import java.util.List; import org.springframework.stereotype.Component;
@Component public class MyBatisTicketCommentAdapter implements TicketCommentPort { private final TicketCommentMapper mapper; public MyBatisTicketCommentAdapter(TicketCommentMapper mapper){this.mapper=mapper;} public TicketComment add(Long tenantId,Long ticketId,Long authorMembershipId,String content){TicketCommentEntity entity=new TicketCommentEntity();entity.tenantId=tenantId;entity.ticketId=ticketId;entity.authorMembershipId=authorMembershipId;entity.content=content;entity.createdAt=Instant.now();mapper.insert(entity);return comment(entity);} public List<TicketComment> list(Long tenantId,Long ticketId){return mapper.selectList(new QueryWrapper<TicketCommentEntity>().eq("tenant_id",tenantId).eq("ticket_id",ticketId).orderByAsc("created_at")).stream().map(this::comment).toList();} private TicketComment comment(TicketCommentEntity entity){return new TicketComment(entity.id,entity.ticketId,entity.authorMembershipId,entity.content,entity.createdAt);}}
